pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 id, uint256 salt, uint256 delay, uint8 fuzz_action) public {
        vm.assume(delay >= 0 && delay <= 365 days);
        // Action selector: 0 = schedule+execute then cancel, 1 = schedule but not ready then cancel, 2 = schedule with long delay then cancel before ready
        address target = address(this);
        bytes memory data = "";
        bytes32 predecessor = bytes32(uint256(0));
        bytes32 scheduledId = keccak256(abi.encode(target, uint256(0), data, predecessor, bytes32(salt)));
        vm.warp(1000);
        c.schedule(target, 0, data, predecessor, bytes32(salt), delay);
        if (fuzz_action % 3 == 0) {
            // Execute then cancel (operation becomes DONE)
            vm.warp(block.timestamp + delay + 1);
            c.execute(target, 0, data, predecessor, bytes32(salt));
        } else if (fuzz_action % 3 == 1) {
            // Schedule but not ready — should be PENDING; cancel it
            vm.warp(block.timestamp + delay/2);
            if (block.timestamp < 1000 + delay && block.timestamp > 1000) {} // Already in valid state
        } else {
            // Schedule with long delay, cancel before ready
            vm.warp(1000);
        }
        c.cancel(scheduledId);
        bool isPending = c.isOperationPending(scheduledId);
        assertTrue(!isPending);
    }
}

