pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, uint8 delay, uint8 warpAmount) public {
        vm.assume(delay > 0);
        vm.assume(warpAmount >= delay);
        vm.warp(block.timestamp + warpAmount);
        address target = address(0x1234);
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        // Schedule with nonzero delay so operation becomes pending, then we may warp to make it ready or done
        vm.startPrank(address(this));
        c.schedule(target, 0, data, predecessor, salt, delay);
        vm.stopPrank();
        // Advance time so the operation is no longer pending (i.e., timestamp <= block.timestamp)
        // Now the operation is either ready or done depending on block.timestamp vs original timestamp
        // cancel should revert per reference, but mutant allows it
        // We capture revert behavior of cancel
        bool refReverted = true;
        try c.cancel(id) { refReverted = false; } catch { refReverted = true; }
        // The reference must revert because cancel requires isOperationPending(id) (timestamp > _DONE_TIMESTAMP),
        // but after advancing beyond delay, timestamp <= block.timestamp, so isOperationPending(id) == false.
        // Therefore assert that reference always reverts.
        assertTrue(refReverted);
    }
}

