contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 id, address sender) public {
        vm.assume(!c.isOperationPending(id));
        vm.assume(sender != address(0));

        // Grant PROPOSER_ROLE to sender so they can call cancel
        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), sender);

        vm.prank(sender);
        try c.cancel(id) returns (bool) {
            // If cancel did not revert, the reference would never reach here when operation is not pending.
            assertTrue(false);
        } catch {
            // The reference must revert; the mutant will succeed (not revert) for some id that is not pending.
            assertTrue(true);
        }
    }
}

